using System;using System.IO;using System.Drawing;using System.Threading.Tasks;using System.Windows.Forms;using System.Diagnostics;
static class Updater{
 [STAThread]static int Main(string[] args){if(args.Length==2&&args[0]=="--verify-release"){try{File.WriteAllText(args[1],Deployment.DownloadAndInstall(s=>{},true));return 0;}catch(Exception e){File.WriteAllText(args[1],"Verification failed: "+e.GetType().Name);return 2;}}Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);
 if(args.Length==1&&args[0]=="--uninstall"){if(Deployment.HostRunning()){MessageBox.Show("Stop LifeAC Lighting from its tray menu first.");return 1;}if(MessageBox.Show("Remove the LifeAC Lighting application and shortcuts? Your show data, accounts and backups will be kept.","Uninstall LifeAC Lighting",MessageBoxButtons.OKCancel)!=DialogResult.OK)return 0;string copy=Path.Combine(Path.GetTempPath(),"LifeAC-Uninstall-"+Guid.NewGuid().ToString("N")+".exe");File.Copy(System.Reflection.Assembly.GetExecutingAssembly().Location,copy);Process.Start(new ProcessStartInfo(copy,"--remove-installation"){UseShellExecute=true});return 0;}
 if(args.Length==1&&args[0]=="--remove-installation"){try{Deployment.RemoveInstallation();MessageBox.Show("LifeAC Lighting was removed. Shows and backups remain in your local app-data folder.");return 0;}catch(Exception e){MessageBox.Show("Uninstall could not complete ("+e.GetType().Name+"). Show data was retained.");return 1;}}
 Application.Run(new UpdateWindow());return 0;}
}
sealed class UpdateWindow:Form{
 Label status=new Label();Button update=new Button();bool busy;
 public UpdateWindow(){Text="Update LifeAC Lighting";Size=new Size(590,320);StartPosition=FormStartPosition.CenterScreen;Font=new Font("Segoe UI",11);BackColor=Color.FromArgb(243,247,246);Controls.Add(new Label{Text="LifeAC Lighting",Dock=DockStyle.Top,Height=75,Padding=new Padding(24),BackColor=Color.FromArgb(46,88,110),ForeColor=Color.White,Font=new Font("Segoe UI",19,FontStyle.Bold)});status.SetBounds(26,95,525,85);status.Text="Get the latest GitHub release. Close the lighting host first; updates never stop live output for you.";Controls.Add(status);update.Text="Check and install update";update.SetBounds(26,195,300,48);Controls.Add(update);update.Click+=async(s,e)=>{busy=true;update.Enabled=false;try{string exe=await Task.Run(()=>Deployment.DownloadAndInstall(Update));if(exe!=null)Update("Update installed. Open LifeAC Lighting using its shortcut. Previous releases and your shows were retained.");}catch(Exception ex){Update(ex is InvalidOperationException?ex.Message:"Update failed ("+ex.GetType().Name+"). Check internet/repository access. Your current installation and shows remain available.");}finally{busy=false;update.Enabled=true;}};FormClosing+=(s,e)=>{if(busy)e.Cancel=true;};}
 void Update(string text){if(InvokeRequired){BeginInvoke((Action)(()=>Update(text)));return;}status.Text=text;}
}
